import{_ as t,a as o,o as a,a4 as r}from"./chunks/framework.-FZumj2l.js";const h=JSON.parse('{"title":"Cart Rules","description":"","frontmatter":{"outline":false},"headers":[],"relativePath":"api/graphql-api/admin/marketing/promotions/cart-rules/index.md","filePath":"api/graphql-api/admin/marketing/promotions/cart-rules/index.md","lastUpdated":1783327468000}'),d={name:"api/graphql-api/admin/marketing/promotions/cart-rules/index.md"};function n(i,e,c,s,l,p){return a(),o("div",null,e[0]||(e[0]=[r('<h1 id="cart-rules" tabindex="-1">Cart Rules <a class="header-anchor" href="#cart-rules" aria-label="Permalink to &quot;Cart Rules&quot;">​</a></h1><p>A <strong>cart rule</strong> discounts the <strong>cart at checkout</strong> — unlike a catalog rule, which lowers a product&#39;s price before it is ever added to a cart. A cart rule can apply automatically when its conditions match, or be gated behind a coupon code the shopper enters. It mirrors the admin <strong>Marketing → Promotions → Cart Rules</strong> screen.</p><h2 id="how-a-cart-rule-works" tabindex="-1">How a cart rule works <a class="header-anchor" href="#how-a-cart-rule-works" aria-label="Permalink to &quot;How a cart rule works&quot;">​</a></h2><p>A rule has three parts: <strong>who it applies to</strong>, <strong>when it applies</strong>, and <strong>what it does to the cart</strong>.</p><ul><li><strong>Who</strong> — <code>channels</code> (which storefront channels) and <code>customerGroups</code> (e.g. general, wholesale). A rule only fires for shoppers in a matching channel + group.</li><li><strong>When</strong> — an optional date window (<code>startsFrom</code> / <code>endsTill</code>, where <code>endsTill</code> must be <code>&gt;= startsFrom</code>) and a set of <code>conditions</code> (cart / product filters such as <em>subtotal &gt; $100</em> or <em>category = Summer</em>). <code>conditionType</code> decides whether <strong>all</strong> conditions must match (<code>1</code>) or <strong>any</strong> (<code>0</code>).</li><li><strong>What</strong> — the <code>actionType</code> + <code>discountAmount</code> decide the discount:</li></ul><table tabindex="0"><thead><tr><th><code>actionType</code></th><th>Effect</th></tr></thead><tbody><tr><td><code>by_percent</code></td><td>Reduce the cart by N% (<code>discountAmount</code> capped at <code>100</code>)</td></tr><tr><td><code>by_fixed</code></td><td>Reduce each matching item by a fixed amount</td></tr><tr><td><code>cart_fixed</code></td><td>Reduce the whole cart by a fixed amount</td></tr><tr><td><code>buy_x_get_y</code></td><td>Buy-X-get-Y free, driven by <code>discountQuantity</code> and <code>discountStep</code></td></tr></tbody></table><p><strong>Coupons.</strong> <code>couponType</code> controls whether a code is needed:</p><ul><li><code>0</code> — no coupon; the rule <strong>auto-applies</strong> whenever its conditions match.</li><li><code>1</code> — a <strong>specific coupon code</strong> is required. When <code>useAutoGeneration</code> is <code>0</code>, you supply a unique <code>couponCode</code> (the rule&#39;s single primary code); bulk codes are managed through the <a href="/api/graphql-api/admin/marketing/promotions/cart-rule-coupons-list.html">Cart Rule Coupons</a> sub-resource.</li></ul><p><strong>Shipping.</strong> <code>freeShipping</code> (<code>1</code>) grants free shipping; <code>applyToShipping</code> (<code>1</code>) extends the discount to the shipping amount too.</p><p><strong>Priority and stacking.</strong> <code>sortOrder</code> sets evaluation priority (lower runs first). <code>endOtherRules</code> (<code>1</code>) stops any lower-priority rule from also applying once this one matches.</p><p><strong>Status and usage.</strong> <code>status</code> (<code>0</code>/<code>1</code>) toggles the rule on. <code>timesUsed</code>, <code>usagePerCustomer</code>, and <code>usesPerCoupon</code> track and cap how often the rule and its coupons can be redeemed (<code>0</code> = unlimited). <code>timesUsed</code> is read-only.</p><h2 id="operations-in-this-menu" tabindex="-1">Operations in this menu <a class="header-anchor" href="#operations-in-this-menu" aria-label="Permalink to &quot;Operations in this menu&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Action</th><th>Operation</th></tr></thead><tbody><tr><td><a href="/api/graphql-api/admin/marketing/promotions/cart-rules-list.html">List</a></td><td><code>adminMarketingCartRules</code> query</td></tr><tr><td><a href="/api/graphql-api/admin/marketing/promotions/cart-rules-detail.html">Detail</a></td><td><code>adminMarketingCartRule</code> query</td></tr><tr><td><a href="/api/graphql-api/admin/marketing/promotions/cart-rules-create.html">Create</a></td><td><code>createAdminMarketingCartRule</code> mutation</td></tr><tr><td><a href="/api/graphql-api/admin/marketing/promotions/cart-rules-update.html">Update</a></td><td><code>updateAdminMarketingCartRule</code> mutation</td></tr><tr><td><a href="/api/graphql-api/admin/marketing/promotions/cart-rules-copy.html">Copy</a></td><td><code>copyAdminMarketingCartRule</code> mutation</td></tr><tr><td><a href="/api/graphql-api/admin/marketing/promotions/cart-rules-delete.html">Delete</a></td><td><code>deleteAdminMarketingCartRule</code> mutation</td></tr><tr><td><a href="/api/graphql-api/admin/marketing/promotions/cart-rules-mass-delete.html">Mass Delete</a></td><td><code>createAdminMarketingCartRuleMassDelete</code> mutation</td></tr></tbody></table><p><code>conditions</code>, <code>channels</code>, and <code>customerGroups</code> resolve only on the <strong>detail</strong> query — they are <code>null</code> on list rows (<code>couponCode</code> is present on both).</p><p>Coupon-gated rules (<code>couponType</code> <code>1</code>) draw their codes from the related <a href="/api/graphql-api/admin/marketing/promotions/cart-rule-coupons-list.html">Cart Rule Coupons</a>.</p><p>All Cart Rules operations require an admin Bearer token — see <a href="/api/graphql-api/admin/authentication.html">Authentication</a>.</p>',16)]))}const m=t(d,[["render",n]]);export{h as __pageData,m as default};
